            int diag = 0;
            for (int c = 1; c <= n; c++) {
                int up = dp[c];
                dp[c] = row[c - 1] == '1' ? 1 + Math.min(diag, Math.min(dp[c], dp[c - 1])) : 0;
                diag = up;
                best = Math.max(best, dp[c]);
            }
        }
        return best * best;
    }
}

